mapper.select:
select sysr.*, (select code from pur_yt_purchase where id = sysr.purchase_id) as purchaseCode, ifnull(sysr.order_sub_code,syos.sub_code) as orderSubCode, ifnull(sysr.order_code,ifnull(syo_by_order.code,syo.code)) as orderCode, su.nick_name as createUserName, syc.name as customerName, pypr.code as productCode from sto_yt_store_record as sysr left join sal_yt_order_sub as syos on sysr.order_sub_id = syos.id and syos.is_deleted = 0 left join sal_yt_order as syo on syos.order_id = syo.id and syo.is_deleted = 0 left join sal_yt_order as syo_by_order on sysr.order_id = syo_by_order.id and syo_by_order.is_deleted = 0 left join sal_yt_customer as syc on ifnull(syo_by_order.customer_id, syo.customer_id) = syc.id and syc.is_deleted = 0 left join pur_yt_purchase as pyp on sysr.purchase_id = pyp.id and pyp.is_deleted = 0 left join pro_yt_product_specification as pyps on pyps.id= sysr.specification_id and pyps.is_deleted=0 left join pro_yt_product as pypr on pyps.product_id = pypr.id and pypr.is_deleted = 0 left join sys_user as su on sysr.create_user = su.user_id and su.is_deleted = 0 where sysr.is_deleted = 0
and sysr.specification_id = #{specificationId}
and sysr.order_sub_id = #{orderSubId}
and ( sysr.order_code like concat('%',#{orderCode},'%') or syo_by_order.code like concat('%',#{orderCode},'%') or syo.code like concat('%',#{orderCode},'%') )
and sysr.purchase_id = #{purchaseId}
and sysr.type = #{type}
and sysr.store_id = #{storeId}
and sysr.customer_store_id = #{customerStoreId}
and sysr.type in
#{item}
and ifnull(sysr.order_sub_code, syos.sub_code) like concat('%', #{orderSubCode}, '%')
and pyp.code like concat('%', #{purchaseCode}, '%')
and su.nick_name like concat('%', #{createUserName}, '%')
and syc.name like concat('%', #{customerName}, '%')
and pypr.code like concat('%', #{productCode}, '%')
and sysr.specification_id in (select product_specification_id from pro_yt_product_specification_item where category_specification_item_id in (select id from pro_yt_category_specification_item where value LIKE CONCAT('%', #{specificationName}, '%')))
order by sysr.create_time desc
